-- 📚 꼭집 주거 사전 — 총자산 1.08억 · 자동차 보유 불허 · 행복주택 대학생 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 🔵 2026-11-09(우편함 「코드·운영 — 모드 정의 하나 … · 📚 재계산 파일 #34·#19」 4장 · 조사 「사전 재계산」 #34) — 「자동차 보유 불허」를
--   car_limit is null or car_limit = 0 으로 센다(분석이 표기를 빈 값 → 0 으로 옮겨 가 빈 값만 세면 12 → 4 로 줄어 보였다 · 뜻은 같다) ·
--   car_null(빈 값) · car_zero(0원)를 따로도 낸다.
-- 확인 2026-11-09 · 실행 약 2초(관리 API 왕복) · 결과:
-- {"n": 22, "by_std": {"행복주택": 21, "희망하우징": 1}, "car_null": 4, "car_zero": 18, "all_asset_anns": 262, "ex": ["SH_312339", "21477_1_충청북도_제천시", "20648_1_경기도_광명시", "20647_1_경기도_광명시"]}
-- (종전 2026-10-13: {"n": 12, "by_std": {"행복주택": 12}, "all_asset_anns": 203} — 빈 값만 센 값)
with a as(select distinct on(x.announcement_id)x.announcement_id,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x order by x.announcement_id,(x.source='LH')desc,x.created_at desc),e as(select distinct ec.announcement_id,coalesce(m.std_type,ec.housing_type)std,ec.asset_limit,ec.car_limit from eligibility_criteria ec join a on a.announcement_id=ec.announcement_id and a.yr=2026 left join housing_type_map m on m.source_table='eligibility_criteria' and m.housing_type=ec.housing_type where ec.announcement_id is not null)select json_build_object('n',(select count(distinct announcement_id) from e where asset_limit=108000000 and (car_limit is null or car_limit=0)),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from e where asset_limit=108000000 and (car_limit is null or car_limit=0) group by 1)q),'car_null',(select count(distinct announcement_id) from e where asset_limit=108000000 and car_limit is null),'car_zero',(select count(distinct announcement_id) from e where asset_limit=108000000 and car_limit=0),'all_asset_anns',(select count(distinct announcement_id) from e where asset_limit is not null),'ex',(select json_agg(i) from(select distinct announcement_id i from e where asset_limit=108000000 and (car_limit is null or car_limit=0) order by 1 desc limit 4)q))j;
